def reserve_gpu(frac=0.80):
    """预留显存池：让 PyTorch 缓存分配器占住每卡约 80% 显存，FFT/MUSIC 大批量计算时不会 OOM、也不会抖动"""
    if not torch:
        return
    for g in GPUS:
        try:
            free, total = torch.cuda.mem_get_info(g["id"])
            want = int(total * frac) - (total - free)
            if want > 256 * 2**20:
                x = torch.empty(want, dtype=torch.uint8, device="cuda:%d" % g["id"])
                del x
            g["reserved_mb"] = int(torch.cuda.memory_reserved(g["id"]) / 2**20)
        except Exception as e:
            ev("warn", "显存预留失败 cuda:%d %s" % (g["id"], e))

def poll_gpu():
    try:
        out = subprocess.run(["nvidia-smi", "--query-gpu=utilization.gpu,memory.used,memory.total", "--format=csv,noheader,nounits"],
                             capture_output=True, text=True, timeout=4).stdout.strip().splitlines()
        u, mu, mt = [], [], []
        for ln in out:
            a = [x.strip() for x in ln.split(",")]
            u.append(float(a[0])); mu.append(float(a[1])); mt.append(float(a[2]))
        GPU_STAT.update(util=u, mem_used=mu, mem_total=mt, t=time.time())
    except Exception:
        pass

