# ----------------------------------------------------------------------------- 原始数据滚动落盘
class RawWriter:
    def __init__(self):
        self.ok = False; self.bytes = 0; self.f = None; self.fsize = 0; self.lock = threading.Lock()
        try:
            os.makedirs(RAW_DIR, exist_ok=True); self.ok = True
        except Exception:
            pass
    def write(self, recs):
        if not self.ok or not recs:
            return
        try:
            with self.lock:
                if self.f is None or self.fsize > 64 * 2**20:
                    if self.f: self.f.close()
                    self.f = open(os.path.join(RAW_DIR, "csi_%d.bin" % int(time.time())), "ab"); self.fsize = 0
                    self._rotate()
                for r in recs:
                    b = np.float64(r[0]).tobytes() + bytes([r[3] & 255, r[4] & 255]) + bytes.fromhex(r[5]) + r[6]
                    self.f.write(b); self.fsize += len(b); self.bytes += len(b)
                self.f.flush()
        except Exception as e:
            ERRORS["rawdisk"] += 1
    def _rotate(self):
        try:
            fs = sorted([os.path.join(RAW_DIR, x) for x in os.listdir(RAW_DIR)], key=os.path.getmtime)
            tot = sum(os.path.getsize(x) for x in fs)
            while tot > RAW_CAP_GB * 2**30 and len(fs) > 1:
                tot -= os.path.getsize(fs[0]); os.remove(fs.pop(0))
        except Exception:
            pass
RAW = RawWriter()

# ----------------------------------------------------------------------------- DSP
def decode_csi(raw128):
    a = np.frombuffer(raw128, dtype=np.int8).astype(np.float32)
    return a[1::2] + 1j * a[0::2]                 # ESP32: 每个子载波先 虚部 再 实部

def to53(H64):
    """N×64(ESP 顺序 0..31,-32..-1) -> N×53 (-26..26)，DC 用邻点插值"""
    H = H64[:, IDX64].copy()
    H[:, 26] = 0.5 * (H[:, 25] + H[:, 27])
    return H

def align(H, ref):
    """用互谱 H·conj(ref) 的线性相位(斜率=采样时刻偏差 STO，截距=载波相位 CFO)把每包对齐到参考；再按 RMS 归一化(消除 AGC)"""
    Cx = H * np.conj(ref)[None, :]
    ph = np.unwrap(np.angle(Cx), axis=1)
    ks = KS.astype(np.float64)
    a = (ph @ ks) / (ks @ ks)
    b = ph.mean(1)
    Hs = H * np.exp(-1j * (a[:, None] * ks[None, :] + b[:, None]))
    rms = np.sqrt((np.abs(Hs) ** 2).mean(1, keepdims=True)) + 1e-6
    return (Hs / rms).astype(np.complex64)

def maxpool(y, n):
    idx = np.linspace(0, len(y), n + 1).astype(int)
    return np.array([y[idx[i]:max(idx[i + 1], idx[i] + 1)].max() for i in range(n)])

def find_peaks(y, x, rel, min_sep, top):
    ymax = float(y.max()) if len(y) else 0.0
    if ymax <= 0:
        return []
    cand = [i for i in range(1, len(y) - 1) if y[i] >= y[i - 1] and y[i] > y[i + 1] and y[i] >= rel * ymax]
    cand.sort(key=lambda i: -y[i])
    out = []
    for i in cand:
        if all(abs(x[i] - x[j]) >= min_sep for j in out):
            out.append(i)
        if len(out) >= top:
            break
    return out

# 剖面坐标：允许主径前后各 6m 余量，之后以静态主径为 0 对齐
RES_M = C_LIGHT / (NFFT * DF)
N_NEG = int(6.0 / RES_M); N_POS = int((P_MAX + 6.0) / RES_M)
NIDX = np.arange(-N_NEG, N_POS)
PM = NIDX * RES_M                                  # 绝对路径坐标 m
KMOD = (KS % NFFT).astype(np.int64)

def ifft_profiles(Hs, ref):
    """GPU0：65536 点零填充 IFFT。返回 (静态剖面, 动态剖面)，均沿 PM 坐标"""
    t = time.time()
    N = Hs.shape[0]
    if torch is not None:
        try:
            dev = DEV0
            x = torch.as_tensor(Hs, device=dev)
            mean = x.mean(0, keepdim=True)
            pad = torch.zeros((N + 1, NFFT), dtype=torch.complex64, device=dev)
            km = torch.as_tensor(KMOD, device=dev)
            pad[:N, km] = x - mean
            pad[N, km] = torch.as_tensor(ref, device=dev)
            cir = torch.fft.ifft(pad, dim=1)
            idx = torch.as_tensor(NIDX % NFFT, device=dev)
            cir = cir[:, idx].abs()
            dyn = torch.sqrt((cir[:N] ** 2).mean(0))
            sta = cir[N]
            r = (sta.cpu().numpy(), dyn.cpu().numpy())
            GPU_MS["ifft"] = (time.time() - t) * 1000
            return r
        except Exception as e:
            ERRORS["ifft_gpu"] += 1
            if ERRORS["ifft_gpu"] < 3: ev("warn", "GPU IFFT 异常，回退 CPU: %s" % e)
    mean = Hs.mean(0)
    pad = np.zeros((Hs.shape[0] + 1, NFFT), dtype=np.complex64)
    pad[:-1, KMOD] = Hs - mean
    pad[-1, KMOD] = ref
    cir = np.abs(np.fft.ifft(pad, axis=1)[:, NIDX % NFFT])
    GPU_MS["ifft"] = (time.time() - t) * 1000
    return cir[-1], np.sqrt((cir[:-1] ** 2).mean(0))

L_SUB = 26
PGRID = np.arange(-6.0, P_MAX + 6.0, 0.25)
def music_profile(Hs):
    """GPU1：子载波空间平滑 + 前后向平均 协方差 → 特征分解 → 噪声子空间伪谱(超分辨)。返回 (伪谱 over PGRID, 估计的径数)"""
    t = time.time()
    N = Hs.shape[0]
    nsub = 53 - L_SUB + 1
    tau = PGRID / C_LIGHT
    m = np.arange(L_SUB)
    A = np.exp(-2j * np.pi * DF * np.outer(m, tau)).astype(np.complex64)      # L × G
    if torch is not None:
        try:
            dev = DEV1
            x = torch.as_tensor(Hs, device=dev)
            sub = torch.stack([x[:, s:s + L_SUB] for s in range(nsub)], 1).reshape(-1, L_SUB)    # (N·nsub)×L
            R = (sub.T @ sub.conj()) / sub.shape[0]
            J = torch.flip(torch.eye(L_SUB, dtype=torch.complex64, device=dev), dims=(0, 1))
            R = 0.5 * (R + J @ R.conj() @ J)
            w, V = torch.linalg.eigh(R.to(torch.complex64))
            wn = w.cpu().numpy()
            p = int(np.clip((wn > 0.08 * wn.max()).sum(), 1, 5))
            En = V[:, :L_SUB - p]
            At = torch.as_tensor(A, device=dev)
            den = (En.conj().T @ At).abs().pow(2).sum(0)
            P = (1.0 / (den + 1e-9)).cpu().numpy()
            GPU_MS["music"] = (time.time() - t) * 1000
            return P, p
        except Exception as e:
            ERRORS["music_gpu"] += 1
            if ERRORS["music_gpu"] < 3: ev("warn", "GPU MUSIC 异常，回退 CPU: %s" % e)
    sub = np.stack([Hs[:, s:s + L_SUB] for s in range(nsub)], 1).reshape(-1, L_SUB)
    R = (sub.T @ sub.conj()) / sub.shape[0]
    J = np.eye(L_SUB)[::-1]
    R = 0.5 * (R + J @ R.conj() @ J)
    w, V = np.linalg.eigh(R)
    p = int(np.clip((w > 0.08 * w.max()).sum(), 1, 5))
    En = V[:, :L_SUB - p]
    den = (np.abs(En.conj().T @ A) ** 2).sum(0)
    GPU_MS["music"] = (time.time() - t) * 1000
    return 1.0 / (den + 1e-9), p

def _pc_peak(X, win, fr, band, refb, nf):
    F = np.fft.rfft(X * win, n=nf, axis=0)
    pw = np.abs(F) ** 2
    score = pw[band].sum(0) / (pw[refb].sum(0) + 1e-9)
    top = np.argsort(-score)[:8]
    U, S, Vt = np.linalg.svd(X[:, top] * win, full_matrices=False)
    sp = np.abs(np.fft.rfft(U[:, 0] * S[0], n=nf)) ** 2
    bi = np.where(band)[0]
    pk = bi[np.argmax(sp[bi])]
    # 抛物线插值细化谱峰
    d = 0.0
    if 0 < pk < len(sp) - 1:
        y0, y1, y2 = np.log(sp[pk - 1] + 1e-12), np.log(sp[pk] + 1e-12), np.log(sp[pk + 1] + 1e-12)
        den = y0 - 2 * y1 + y2
        d = 0.5 * (y0 - y2) / den if abs(den) > 1e-9 else 0.0
    return float(sp[pk] / (np.median(sp[refb]) + 1e-12)), float((pk + d) * (fr[1] - fr[0]))

def breathing_est(t, A, fs_target=10.0):
    """幅度时间序列 → 均匀重采样 → 0.15~0.6Hz 带内子载波 PCA → 谱峰；用「每个子载波独立随机移位」的替身数据做零假设检验，抑制噪声假阳性"""
    span = t[-1] - t[0]
    if len(t) < 120 or span < 14:
        return {"ok": False, "why": "数据不足(需≥14s)", "span": round(float(span), 1)}
    tu = np.arange(t[0], t[-1], 1.0 / fs_target)
    X = np.stack([np.interp(tu, t, A[:, k]) for k in range(A.shape[1])], 1)
    X = X - X.mean(0)
    n = len(tu); nf = 4096
    win = np.hanning(n)[:, None]
    fr = np.fft.rfftfreq(nf, 1.0 / fs_target)
    band = (fr >= 0.15) & (fr <= 0.6); refb = (fr >= 0.05) & (fr <= 2.0)
    snr, f = _pc_peak(X, win, fr, band, refb, nf)
    rng = np.random.default_rng(1)
    sur = []
    for _ in range(3):
        Xs = np.stack([np.roll(X[:, k], int(rng.integers(n // 8, n - n // 8))) for k in range(X.shape[1])], 1)
        sur.append(_pc_peak(Xs, win, fr, band, refb, nf)[0])
    ratio = snr / (max(sur) + 1e-9)
    return {"ok": bool(snr > 30.0), "bpm": round(f * 60, 1), "snr": round(snr, 1), "ratio": round(ratio, 1), "span": round(float(span), 1)}

# ----------------------------------------------------------------------------- 核心处理器
class Radar:
    def __init__(self):
        self.lock = threading.Lock()
        self.q = collections.deque(maxlen=30000)
        self.Hb = np.zeros((HIST, 53), dtype=np.complex64)
        self.tb = np.zeros(HIST, dtype=np.float64)
        self.rb = np.zeros(HIST, dtype=np.float32)
        self.n = 0
        self.ref = None
        self.frozen = False
        self.calib_buf = []
        self.calib_want = 0
        self.noise = None
        self.mstate = False
        self.dev = {}
        self.esp = {"last": 0, "via": "", "n_batches": 0, "n_recs": 0, "stat": {}, "fw": "", "times": collections.deque(maxlen=400)}
        self.baseline_m = 3.0
        self.snap = b"{}"
        self.snap_obj = {}
        self.sense = {}
        self.objects = []
        self.profile = {}
        self.amp_last = None
        self.log_esp = collections.deque(maxlen=150)

    # ------- ingest (HTTP 线程里调用：只做解码+入队，绝不做重计算)
    def ingest(self, body):
        now = time.time()
        recs = body.get("recs") or []
        bt = body.get("t")
        out = []
        for r in recs:
            try:
                ms, rssi, ch, mac, ap, b64 = r[0], r[1], r[2], r[3], r[4], r[5]
                raw = base64.b64decode(b64)
                if len(raw) < 128:
                    continue
                d = 0.0
                if bt is not None:
                    dd = (int(bt) - int(ms)) & 0xFFFFFFFF
                    d = dd / 1000.0 if dd < 600000 else 0.0
                out.append((now - d, ms, int(rssi), int(ch), int(ap), str(mac), raw[:128]))
            except Exception:
                ERRORS["bad_rec"] += 1
        with self.lock:
            self.q.extend(out)
            e = self.esp
            e["last"] = now; e["via"] = body.get("via", "?"); e["fw"] = body.get("fw", e.get("fw"))
            e["n_batches"] += 1; e["n_recs"] += len(out)
            if isinstance(body.get("stat"), dict):
                e["stat"] = body["stat"]
            for ln in (body.get("log") or [])[-30:]:
                self.log_esp.append(str(ln)[:300])
        RAW.write([(o[0], o[1], o[2], o[3], o[4], o[5], o[6]) for o in out])
        return len(out)

    # ------- compute thread
    def step(self):
        with self.lock:
            items = list(self.q); self.q.clear()
        ap_items = [x for x in items if x[4] == 1]
        for x in items:
            if x[4] == 0:
                d = self.dev.setdefault(x[5], {"n": 0, "rssi": x[2], "t": 0, "ch": x[3], "t0": x[0]})
                d["n"] += 1; d["t"] = x[0]; d["ch"] = x[3]; d["rssi"] = 0.8 * d["rssi"] + 0.2 * x[2]
        if ap_items:
            H64 = np.stack([decode_csi(x[6]) for x in ap_items])
            H = to53(H64)
            if self.ref is None:
                self.ref = np.zeros(53, dtype=np.complex64)
                first = H[0:1]
                self.ref = align(first, np.ones(53, dtype=np.complex64))[0]
            Hs = align(H, self.ref)
            m = len(ap_items)
            idx = (self.n + np.arange(m)) % HIST
            self.Hb[idx] = Hs
            self.tb[idx] = [x[0] for x in ap_items]
            self.rb[idx] = [x[2] for x in ap_items]
            self.n += m
            self.amp_last = np.abs(Hs[-1])
            if self.calib_want > 0:
                self.calib_buf.append(Hs); got = sum(len(c) for c in self.calib_buf)
                if got >= self.calib_want:
                    allh = np.concatenate(self.calib_buf)
                    self.ref = align(allh, self.ref).mean(0).astype(np.complex64)
                    self.ref /= (np.sqrt((np.abs(self.ref) ** 2).mean()) + 1e-9)
                    A = np.abs(allh); cvs = [float(np.median(A[i:i + 50].std(0) / (A[i:i + 50].mean(0) + 1e-6))) for i in range(0, len(A) - 49, 25)]
                    if cvs: self.noise = float(np.clip(np.median(cvs), 0.012, 0.15)); ev("info", "实测底噪 CV=%.4f" % self.noise)
                    self.frozen = True; self.calib_want = 0; self.calib_buf = []
                    ev("ok", "基线校准完成（%d 帧，已冻结）" % got)
            elif not self.frozen:
                a = 1 - (1 - 0.0015) ** m
                self.ref = ((1 - a) * self.ref + a * Hs.mean(0)).astype(np.complex64)
        self.analyze()

    def last(self, k):
        k = min(k, self.n, HIST)
        idx = (self.n - k + np.arange(k)) % HIST
        return self.Hb[idx], self.tb[idx], self.rb[idx]

    def analyze(self):
        now = time.time()
        sense = {"n": int(self.n), "calibrated": bool(self.frozen), "calibrating": self.calib_want > 0}
        objs = []
        prof = {}
        if self.n >= 40 and self.ref is not None:
            Hs, ts, rs = self.last(256)
            if now - ts[-1] > 5:
                sense["stale"] = True
            Hw = Hs[-min(len(Hs), 50):]
            A = np.abs(Hw)
            cv = np.median(A.std(0) / (A.mean(0) + 1e-6))
            raw_m = float(cv + 0.002 * float(np.std(rs[-50:])))
            if self.noise is None: self.noise = NOISE_INIT          # 绝对物理底噪(幅度变异系数)，不从数据里学，避免把持续运动学成底噪
            if raw_m < self.noise * 1.5: self.noise = 0.98 * self.noise + 0.02 * raw_m
            self.noise = min(max(self.noise, 0.012), NOISE_INIT * 3)
            z = raw_m / self.noise
            if z > 2.4: self.mstate = True
            elif z < 1.7: self.mstate = False
            sense.update(motion=round(raw_m, 4), noise=round(float(self.noise), 4), z=round(float(z), 2), moving=bool(self.mstate), rssi=round(float(rs[-20:].mean()), 1))
            # 剖面
            sta, dyn = ifft_profiles(Hs, self.ref)
            n0 = int(np.argmax(sta))
            p_main = PM[n0]
            P, npaths = music_profile(Hs.mean(0, keepdims=True))
            pm = PM - p_main
            sel = (pm >= 0) & (pm <= P_MAX)
            xs = pm[sel]
            xi = np.linspace(0, P_MAX, NDISP, endpoint=False)
            ys = maxpool(sta[sel], NDISP); yd = maxpool(dyn[sel], NDISP)
            pg = PGRID - p_main; psel = (pg >= 0) & (pg <= P_MAX)
            ym = np.interp(xi, pg[psel], P[psel]) if psel.any() else np.zeros(NDISP)
            ymax = lambda y: float(y.max()) + 1e-12
            gs = max(ymax(ys), 1e-9)
            prof = {"axis_max": P_MAX, "static": np.round(ys / gs, 3).tolist(), "dynamic": np.round(yd / (gs * 0.35 + 1e-9), 3).clip(0, 1.5).tolist(),
                    "music": np.round(ym / ymax(ym), 3).tolist(), "npaths": npaths, "res_m": round(C_LIGHT / (20e6) , 1)}
            sense["nfft"] = NFFT
            # 呼吸
            Hl, tl, _ = self.last(1500)
            br = breathing_est(tl, np.abs(Hl)) if len(tl) > 150 else {"ok": False, "why": "数据不足"}
            sense["breath"] = br
            # ---- 物体（只报告物理上可靠的：运动 / 呼吸 / 无线设备 / 路由器）
            # 单链路 20MHz 带宽 → 路径分辨率≈15m，且逐包相位对齐会抹掉弱反射体的时延信息，所以运动/呼吸物体【不给假距离】(range_m=None)。
            sel_c = np.abs(self.ref); sense["selectivity"] = round(float(sel_c.std() / (sel_c.mean() + 1e-9)), 3)
            objs.append({"id": "router", "kind": "router", "label": "路由器/热点(网关)", "range_m": 0.0, "conf": 1.0, "ang": 0.0})
            if self.mstate:
                objs.append({"id": "mv", "kind": "moving", "label": "运动物体/人体", "range_m": None,
                             "conf": round(min(1.0, (z - 1.7) / 6 + 0.35), 2), "ang": ang_of("mv"), "z": round(float(z), 1)})
            elif br.get("ok"):
                objs.append({"id": "br", "kind": "breathing", "label": "静止人体(呼吸 %.0f 次/分)" % br["bpm"], "range_m": None,
                             "conf": round(min(1.0, br["snr"] / 100), 2), "ang": ang_of("br"), "bpm": br["bpm"]})
            sense["level"] = "有运动" if self.mstate else ("疑似静止人体(呼吸)" if br.get("ok") else "无人/环境静止")
        # 无线设备
        devs = []
        for mac, d in list(self.dev.items()):
            if now - d["t"] < 20 and d["n"] >= 3:
                dist = 10 ** ((-40.0 - d["rssi"]) / 27.0)
                devs.append({"id": "dv" + mac[-4:], "kind": "device", "label": "无线设备 %s" % ":".join(mac[i:i + 2] for i in range(6, 12, 2)),
                             "range_m": round(min(dist, 40), 1), "conf": round(min(1.0, d["n"] / 30), 2), "ang": ang_of("dv" + mac), "rssi": round(d["rssi"], 0), "mac": mac, "n": d["n"]})
        devs.sort(key=lambda x: -x["conf"])
        objs += devs[:10]
        self.sense, self.objects, self.profile = sense, objs, prof
        self.build_snapshot()

    def build_snapshot(self):
        now = time.time()
        e = self.esp
        times = [t for t in e["times"] if now - t < 5]
        online = (now - e["last"]) < 6 if e["last"] else False
        ap_rate = 0.0
        if self.n > 10:
            Hs, ts, _ = self.last(300)
            rec = ts[ts > now - 5]
            ap_rate = len(rec) / 5.0
        s = {
            "t": now, "v": VERSION, "radar": True, "uptime": int(now - T0),
            "esp": {"online": online, "age": round(now - e["last"], 1) if e["last"] else None, "via": e["via"], "fw": e["fw"], "stat": e["stat"],
                    "batches": e["n_batches"], "recs": e["n_recs"], "rate": round(ap_rate, 1)},
            "sense": self.sense, "objects": self.objects, "profile": self.profile,
            "spectrum": {"amp": np.round(self.amp_last, 3).tolist() if self.amp_last is not None else [],
                         "ref": np.round(np.abs(self.ref), 3).tolist() if self.ref is not None else []},
            "baseline_m": self.baseline_m,
            "host": {"gpus": GPUS, "gpu": GPU_STAT, "ms": {k: round(v, 1) for k, v in GPU_MS.items()}, "nfft": NFFT, "sys": SYS,
                     "raw_mb": round(RAW.bytes / 2**20, 2), "raw_cap_gb": RAW_CAP_GB, "errors": dict(ERRORS), "torch": bool(torch)},
            "tunnels": [tn.info() for tn in TUNNELS],
            "events": list(EVENTS)[-25:], "esp_log": list(self.log_esp)[-40:],
        }
        self.snap_obj = s
        self.snap = json.dumps(s, ensure_ascii=False, separators=(",", ":")).encode("utf-8")

    def calibrate(self, n=150):
        self.calib_buf = []; self.calib_want = n; self.frozen = False
        ev("info", "开始基线校准：请保持环境无人/静止约 %d 帧(~3秒)" % n)

    def reset(self):
        self.n = 0; self.ref = None; self.frozen = False; self.noise = None; self.mstate = False; self.dev = {}; self.calib_want = 0
        ev("info", "已重置")

def ang_of(key):
    h = int(hashlib.md5(key.encode()).hexdigest()[:6], 16)
    return round((h % 3600) / 3600.0 * 2 * math.pi, 3)

SYS = {}
RADAR = Radar()
TUNNELS = []

# ----------------------------------------------------------------------------- 诊断文本
def diag_text():
    s = RADAR.snap_obj or {}
    e = s.get("esp", {})
    st = e.get("stat") or {}
    L = ["## 主机(Kaggle)侧检测"]
    L.append("✅ 主机服务: 运行 %ds · Python %s · numpy %s · 端口 %d · v%s" % (int(time.time() - T0), sys.version.split()[0], np.__version__, PORT, VERSION))
    L.append(("✅" if any(t.url and t.ok for t in TUNNELS) else "❌") + " 公网隧道: " + " | ".join("%s:%s %s" % (t.kind, "✓" if t.ok else "✗", t.url or "-") for t in TUNNELS))
    L.append(("✅ GPU 加速: " + ", ".join("cuda:%d %s %.1fGiB" % (g["id"], g["name"], g["total_mb"] / 1024) for g in GPUS) + " · IFFT→cuda:0 NFFT=%d %.1fms · MUSIC→cuda:1 %.1fms" % (NFFT, GPU_MS["ifft"], GPU_MS["music"])) if GPUS else "⚠️ 没有 GPU：用 CPU 数值路径(NFFT=%d)。Kaggle: Settings→Accelerator→GPU T4 x2" % NFFT)
    sy = SYS
    L.append("ℹ️ 资源: 内存 %s/%s GB · 磁盘剩余 %s/%s GB · CPU %s 核 · 原始数据落盘 %.1f MB (上限 %.0f GB)" % (sy.get("ram_used_gb"), sy.get("ram_total_gb"), sy.get("disk_free_gb"), sy.get("disk_total_gb"), sy.get("cpu"), RAW.bytes / 2**20, RAW_CAP_GB))
    if e.get("online"):
        L.append("✅ ESP32-S3: 在线 · 通路=%s · 固件 %s · CSI 速率 %.1f 条/秒 · 累计 %d 条" % (e.get("via"), e.get("fw"), e.get("rate", 0), e.get("recs", 0)))
        if st:
            L.append("ℹ️ ESP32 状态: WiFi=%s(%s) 信号 %s dBm 信道 %s · 堆 %s · 复位=%s · 看门狗累计复位 %s 次 · 自愈: WiFi %s 次 / CSI %s 次" % (st.get("ssid"), st.get("ip"), st.get("rssi"), st.get("ch"), st.get("heap"), st.get("rst"), st.get("wdtN"), st.get("fixW"), st.get("fixC")))
    else:
        L.append("❌ ESP32-S3: 主机还没收到数据 (最近 %s 秒前)。浏览器点右上角「连接 ESP32」；或检查 config.h 的 WiFi/KAGGLE_URL。" % (e.get("age"),))
    se = s.get("sense", {})
    L.append("ℹ️ 感知: %s · 运动指数 z=%s · 呼吸=%s · 物体 %d 个" % (se.get("level", "无数据"), se.get("z"), (se.get("breath") or {}).get("bpm"), len(s.get("objects", []))))
    L.append("%s 错误计数: %s" % ("✅" if not ERRORS else "⚠️", dict(ERRORS)))
    L.append("\n## 主机事件(最近)")
    L += list(EVENTS)[-25:]
    if RADAR.log_esp:
        L.append("\n## ESP32 串口日志(最近)")
        L += list(RADAR.log_esp)[-30:]
    if CLIENT_LOGS:
        L.append("\n## 浏览器事件(最近)")
        L += list(CLIENT_LOGS)[-20:]
    return "\n".join(L)

# ----------------------------------------------------------------------------- HTTP
def file_by_id(fid):
    for f in ASSETS.get("files", []):
        if f["id"] == fid:
            return f
    return None

class Handler(BaseHTTPRequestHandler):
    protocol_version = "HTTP/1.1"
    timeout = 30
    def log_message(self, *a):
        pass
    def _send(self, code, body, ctype="application/json; charset=utf-8", cache=False):
        if isinstance(body, str):
            body = body.encode("utf-8")
        try:
            self.send_response(code)
            self.send_header("Content-Type", ctype)
            self.send_header("Content-Length", str(len(body)))
            self.send_header("Access-Control-Allow-Origin", "*")
            self.send_header("Access-Control-Allow-Headers", "*")
            self.send_header("Access-Control-Allow-Methods", "GET,POST,OPTIONS")
            self.send_header("Access-Control-Allow-Private-Network", "true")
            self.send_header("Access-Control-Max-Age", "86400")
            self.send_header("Cache-Control", "public, max-age=60" if cache else "no-store")
            self.end_headers()
            self.wfile.write(body)
        except (BrokenPipeError, ConnectionResetError, TimeoutError):
            self.close_connection = True
    def do_OPTIONS(self):
        self._send(204, b"")
    def _body(self):
        n = int(self.headers.get("Content-Length") or 0)
        if n > 4 * 2**20:
            return None
        return self.rfile.read(n) if n else b""
    def do_GET(self):
        try:
            p = self.path.split("?")[0]
            if p in ("/", "/index.html"):
                return self._send(200, ASSETS["app"], "text/html; charset=utf-8")
            if p == "/api/health":
                return self._send(200, json.dumps({"ok": True, "radar": True, "kind": "kaggle", "v": VERSION, "uptime": int(time.time() - T0), "t": time.time()}))
            if p == "/api/state":
                return self._send(200, RADAR.snap)
            if p == "/api/diag":
                return self._send(200, diag_text(), "text/plain; charset=utf-8")
            if p == "/api/code":
                return self._send(200, json.dumps([{k: v for k, v in f.items() if k != "content"} | {"size": len(f["content"])} for f in ASSETS.get("files", [])], ensure_ascii=False))
            if p.startswith("/api/code/"):
                f = file_by_id(p[len("/api/code/"):])
                return self._send(200, json.dumps(f, ensure_ascii=False)) if f else self._send(404, "{}")
            self._send(404, json.dumps({"error": "not found"}))
        except Exception:
            ERRORS["http_get"] += 1
            self._send(500, json.dumps({"error": traceback.format_exc()[-300:]}))
    def do_POST(self):
        try:
            p = self.path.split("?")[0]
            raw = self._body()
            if raw is None:
                return self._send(413, "{}")
            key = self.headers.get("X-API-Key")
            if p == "/api/ingest":
                if key and key != API_KEY:
                    return self._send(401, json.dumps({"ok": False, "error": "bad key"}))
                body = json.loads(raw.decode("utf-8"))
                n = RADAR.ingest(body)
                return self._send(200, json.dumps({"ok": True, "n": n, "urls": [t.url for t in TUNNELS if t.ok and t.url], "t": time.time()}))
            body = json.loads(raw.decode("utf-8")) if raw else {}
            if p == "/api/calibrate":
                RADAR.calibrate(int(body.get("frames", 150)))
                return self._send(200, '{"ok":true}')
            if p == "/api/reset":
                RADAR.reset()
                return self._send(200, '{"ok":true}')
            if p == "/api/config":
                if "baseline_m" in body:
                    RADAR.baseline_m = float(body["baseline_m"])
                return self._send(200, '{"ok":true}')
            if p == "/api/clientlog":
                for ln in (body.get("lines") or [])[-30:]:
                    CLIENT_LOGS.append(str(ln)[:300])
                return self._send(200, '{"ok":true}')
            self._send(404, "{}")
        except Exception:
            ERRORS["http_post"] += 1
            self._send(400, json.dumps({"ok": False, "error": traceback.format_exc()[-300:]}))

class Server(ThreadingHTTPServer):
    daemon_threads = True
    allow_reuse_address = True
    request_queue_size = 256

# ----------------------------------------------------------------------------- 隧道守护
def ensure_cloudflared():
    p = "/tmp/cloudflared"
    if os.path.exists(p) and os.path.getsize(p) > 10_000_000:
        return p
    ev("info", "下载 cloudflared …")
    urllib.request.urlretrieve("https://github.com/cloudflare/cloudflared/releases/latest/download/cloudflared-linux-amd64", p)
    os.chmod(p, 0o755)
    return p

SSH_BASE = ["ssh", "-o", "StrictHostKeyChecking=no", "-o", "UserKnownHostsFile=/dev/null", "-o", "ServerAliveInterval=15", "-o", "ServerAliveCountMax=3",
            "-o", "ExitOnForwardFailure=yes", "-o", "LogLevel=ERROR"]

class Tunnel(threading.Thread):
    def __init__(self, kind):
        super().__init__(daemon=True)
        self.kind = kind; self.url = ""; self.ok = False; self.proc = None; self.fails = 0; self.restarts = 0; self.lat = 0; self.since = 0; self.proto = "http2"
        self.conn = None
    def info(self):
        return {"kind": self.kind, "url": self.url, "ok": self.ok, "lat": self.lat, "restarts": self.restarts}
    def cmd(self):
        if self.kind == "cloudflared":
            return [ensure_cloudflared(), "tunnel", "--no-autoupdate", "--protocol", self.proto, "--edge-ip-version", "4", "--url", "http://127.0.0.1:%d" % PORT], r"https://[a-z0-9-]+\.trycloudflare\.com"
        if self.kind == "pinggy":
            return SSH_BASE + ["-p", "443", "-R0:127.0.0.1:%d" % PORT, "a.pinggy.io"], r"https://[a-z0-9-]+\.(?:a\.)?free\.pinggy\.(?:net|link)"
        return SSH_BASE + ["-R", "80:127.0.0.1:%d" % PORT, "nokey@localhost.run"], r"https://[a-z0-9]+\.lhr\.life"
    def check(self, timeout=8):
        t = time.time()
        try:
            host = self.url.split("//")[1]
            if self.conn is None:
                self.conn = http.client.HTTPSConnection(host, timeout=timeout, context=ssl.create_default_context())
            self.conn.request("GET", "/api/health", headers={"Connection": "keep-alive"})
            r = self.conn.getresponse(); b = r.read()
            self.lat = int((time.time() - t) * 1000)
            return r.status == 200 and b"radar" in b
        except Exception:
            try: self.conn and self.conn.close()
            except Exception: pass
            self.conn = None
            return False
    def stop_proc(self):
        try:
            if self.proc and self.proc.poll() is None:
                self.proc.kill()
        except Exception:
            pass
    def run(self):
        while True:
            self.ok = False; self.url = ""; self.fails = 0; self.conn = None
            try:
                cmd, rx = self.cmd()
                self.proc = subprocess.Popen(cmd, stdout=subprocess.PIPE, stderr=subprocess.STDOUT, stdin=subprocess.DEVNULL, text=True, bufsize=1)
                found = {"u": ""}
                def reader():
                    for ln in self.proc.stdout:
                        m = re.search(rx, ln)
                        if m and not found["u"]:
                            found["u"] = m.group(0)
                        if "permission denied" in ln.lower() or "error" in ln.lower():
                            EVENTS.append("%s [warn] %s: %s" % (time.strftime("%H:%M:%S"), self.kind, ln.strip()[:120]))
                threading.Thread(target=reader, daemon=True).start()
                t0 = time.time()
                while time.time() - t0 < 40 and not found["u"] and self.proc.poll() is None:
                    time.sleep(0.5)
                if not found["u"]:
                    raise RuntimeError("40 秒内没拿到网址")
                self.url = found["u"]
                ev("info", "%s 给出网址 %s，正在自检…" % (self.kind, self.url))
                for _ in range(10):
                    time.sleep(2)
                    if self.check(): self.ok = True; break
                if not self.ok:
                    raise RuntimeError("公网自检失败")
                self.since = time.time()
                ev("ok", "%s 公网自检通过 %s (%dms)" % (self.kind, self.url, self.lat))
                while self.proc.poll() is None:
                    time.sleep(8)                                  # 8 秒保活：既预热 HTTP/2 连接，又探测隧道是否真的通
                    if self.check(): self.fails = 0; self.ok = True
                    else:
                        self.fails += 1
                        if self.fails >= 3:
                            raise RuntimeError("保活连续 3 次失败")
            except Exception as e:
                ev("warn", "%s 隧道异常: %s → 5 秒后重启" % (self.kind, e))
                ERRORS["tunnel_" + self.kind] += 1
                if self.kind == "cloudflared": self.proto = "auto" if self.proto == "http2" else "http2"
            self.ok = False; self.stop_proc(); self.restarts += 1
            time.sleep(5)

def ntfy_loop():
    last = ""; lt = 0
    while True:
        try:
            urls = " ".join(t.url for t in TUNNELS if t.ok and t.url)
            if urls and (urls != last or time.time() - lt > 150):
                req = urllib.request.Request("https://ntfy.sh/" + NTFY_TOPIC, data=urls.encode(), method="POST")
                urllib.request.urlopen(req, timeout=8).read()
                if urls != last: ev("info", "网址已发布到 ntfy.sh/%s（浏览器/ESP32 可自动发现）" % NTFY_TOPIC)
                last = urls; lt = time.time()
        except Exception:
            ERRORS["ntfy"] += 1
        time.sleep(10)

def compute_loop():
    k = 0
    while True:
        t = time.time()
        try:
            RADAR.step()
        except Exception:
            ERRORS["compute"] += 1
            if ERRORS["compute"] < 4: ev("error", "计算线程异常: " + traceback.format_exc()[-400:])
        k += 1
        if k % 12 == 0:
            poll_gpu(); SYS.update(sysinfo())
        time.sleep(max(0.02, 0.25 - (time.time() - t)))

def main():
    reserve_gpu()
    SYS.update(sysinfo()); poll_gpu()
    ev("info", "服务启动 · v%s · numpy %s · GPU %d 块 · NFFT=%d" % (VERSION, np.__version__, len(GPUS), NFFT))
    for g in GPUS:
        ev("info", "cuda:%d %s %.1fGiB · 显存池预留 %s MB" % (g["id"], g["name"], g["total_mb"] / 1024, g.get("reserved_mb")))
    srv = Server(("0.0.0.0", PORT), Handler)
    threading.Thread(target=srv.serve_forever, daemon=True).start()
    threading.Thread(target=compute_loop, daemon=True).start()
    if os.environ.get("RADAR_NO_TUNNEL") != "1":
        for k in ("cloudflared", "pinggy", "localhost.run"):
            tn = Tunnel(k); TUNNELS.append(tn); tn.start()
        threading.Thread(target=ntfy_loop, daemon=True).start()
    ev("ok", "本机已就绪 http://127.0.0.1:%d  （等待公网隧道，网址会打印在下面）" % PORT)
    last_urls = ""
    while True:                                    # 主线程：每 30 秒打印心跳（Kaggle 看到持续输出，不会当作空闲而回收）
        for _ in range(30):
            time.sleep(1)
            u = " ".join(t.url for t in TUNNELS if t.ok and t.url)
            if u != last_urls and u:
                last_urls = u
                print("\n" + "=" * 70 + "\n 浏览器打开（任选其一）:\n  " + "\n  ".join(t.url for t in TUNNELS if t.ok and t.url) + "\n" + "=" * 70 + "\n", flush=True)
        e = RADAR.esp
        print("[hb %s] ESP32 %s · CSI %d 条 · GPU %s · 隧道 %s" % (time.strftime("%H:%M:%S"), "在线" if time.time() - e["last"] < 6 else "离线", RADAR.n,
              GPU_STAT.get("util"), ",".join("%s=%s" % (t.kind[:4], "ok" if t.ok else "down") for t in TUNNELS)), flush=True)

if __name__ == "__main__":
    main()
